change_filament_gcode:
;===== Mnemonic3d - MULTIACE MOD =====================
; Change Tool[previous_extruder] -> Tool[next_extruder] (layer [layer_num])

M400

T[next_extruder]

{if layer_num == 0}
M109 S{first_layer_temperature[next_extruder]}
{else}
M109 S{temperature[next_extruder]}
{endif}

{if filament_type[next_extruder] == "PVA"}
SET_VELOCITY_LIMIT ACCEL=3000
{else}
SET_VELOCITY_LIMIT ACCEL=10000
{endif}

{if previous_extruder != next_extruder}
SM_PRINT_PREEXTRUDE_FILAMENT INDEX=[next_extruder]
{endif}

M400
G90
